import { expect, test, uniqueName } from "../../fixtures";

const MiB = 1024 * 1024;

const examples = [
  {
    file: "an empty file",
    kind: "w9",
    status: 422,
    code: "empty_file",
    part: { name: "empty.pdf", mimeType: "application/pdf", buffer: Buffer.alloc(0) },
  },
  {
    file: "a file of exactly 10 MiB + 1",
    kind: "w9",
    status: 413,
    code: "file_too_large",
    part: {
      name: "huge.pdf",
      mimeType: "application/pdf",
      buffer: Buffer.alloc(10 * MiB + 1, 0x61),
    },
  },
  {
    file: 'a ".exe" file',
    kind: "w9",
    status: 415,
    code: "unsupported_type",
    part: {
      name: "setup.exe",
      mimeType: "application/octet-stream",
      buffer: Buffer.from("MZ not a real executable"),
    },
  },
  {
    file: "a valid text file",
    kind: "passport",
    status: 422,
    code: "validation_error",
    part: {
      name: "notes.txt",
      mimeType: "text/plain",
      buffer: Buffer.from("Some vendor notes for the upload test."),
    },
  },
] as const;

test.describe("Upload vendor documents", () => {
  for (const example of examples) {
    test(
      `Reject invalid uploads: upload ${example.file} as kind "${example.kind}"`,
      { tag: "@DOC-04" },
      async ({ apiAs }) => {
        // Background: signed in as member, vendor in status "draft"
        const member = await apiAs("member");
        const created = await member.post("/api/vendors", {
          data: {
            name: uniqueName("DOC-04 Vendor"),
            category: "software",
            contact_email: `doc04-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@vendor.test`,
          },
        });
        expect(created.status()).toBe(201);
        const vendor = await created.json();
        expect(vendor.status).toBe("draft");

        // When I upload <file> as kind "<kind>"
        const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: example.kind,
            file: example.part,
          },
        });

        // Then the response status is <status> and the error code is "<code>"
        expect(response.status()).toBe(example.status);
        const body = await response.json();
        expect(body.error.code).toBe(example.code);
      },
    );
  }
});
